int total = 0;
object sync = new();
int iterations = 100;
Task Work() => Task.Run(() => {
    for (int i = 0; i < iterations; i++)
        lock (sync) { total++; }
});
await Task.WhenAll(Work(), Work());
Console.WriteLine(total);

